insert into public.profiles (id, is_sample, is_organization, name, role, focus, institution, avatar_url) values ('c21bb9e1-f8a7-47cf-84f2-109835f3ee13', true, true, 'Instituto de Computação — UFF', 'Comissão Organizadora', null, 'Universidade Federal Fluminense', 'https://images.unsplash.com/photo-1562774053-701939374585?w=300&auto=format&fit=crop&q=80') on conflict (id) do nothing;
insert into public.projects (id, created_by, is_sample, title, short_description, summary, key_results, methodology, files, institution, area, type, status, project_date, period, tags, url, visual_type, media_url, favorites_base) values ('3e7c8fc8-171b-4514-9686-83a230a95a1b', 'b6f3063e-e60e-49f5-bd47-2e551099e279', true, 'Análise espacial da qualidade do ar no Rio de Janeiro usando dados abertos', 'O projeto utiliza dados de estações de monitoramento e técnicas de geoprocessamento para identificar padrões de poluição na cidade.', 'Este projeto analisa a qualidade do ar na cidade do Rio de Janeiro a partir de dados abertos de estações de monitoramento, combinando técnicas de geoprocessamento e visualização espacial. O objetivo é identificar padrões de poluição, avaliar a influência de fatores urbanos e ambientais, e fornecer insumos para políticas públicas de monitoramento e mitigação.', array['Mapeamento da distribuição de poluentes na cidade.', 'Identificação de áreas críticas de maior concentração.', 'Análise temporal das variações de qualidade do ar.']::text[], 'A metodologia foi estruturada em quatro etapas: (1) Coleta automatizada via API das séries históricas horárias das estações do programa MonitorAr-Rio e dados meteorológicos do INMET; (2) Limpeza, tratamento de falhas e padronização estatística em Python (Pandas/NumPy); (3) Interpolação espacial pelo método IDW (Inverse Distance Weighting) e Krigagem Ordinária utilizando GeoPandas e PostGIS; (4) Cruzamento com malhas viárias e cobertura vegetal para modelagem de regressão espacial.', '[{"name":"relatorio_parcial_pibic_uff_2025.pdf","size":"2.4 MB","type":"Artigo / Relatório PDF"},{"name":"pipeline_geopandas_monitorar_rio.ipynb","size":"840 KB","type":"Jupyter Notebook"},{"name":"malha_estacoes_rj_postgis.geojson","size":"4.1 MB","type":"Dataset GeoJSON"}]'::jsonb, 'Universidade Federal Fluminense (UFF)', 'Dados e Análise', 'Projeto de pesquisa', 'Em andamento', date '2025-04-28', 'jan. 2024 - dez. 2025', array['GeoPandas', 'PostgreSQL', 'Python', 'Rio de Janeiro']::text[], 'https://github.com/capyfolio-demo/qualidade-ar-rio-geopandas', 'spatial-map', 'https://images.unsplash.com/photo-1526778548025-fa2f459cd5c1?w=1000&auto=format&fit=crop&q=80', 42) on conflict (id) do nothing;
