insert into public.project_authors (project_id, profile_id, position) values ('3e7c8fc8-171b-4514-9686-83a230a95a1b', '03f897a3-2f3d-4314-bd11-e19cfb387623', 1) on conflict do nothing;
insert into public.projects (id, created_by, is_sample, title, short_description, summary, key_results, methodology, files, institution, area, type, status, project_date, period, tags, url, visual_type, media_url, favorites_base) values ('442306d0-c2fb-437b-88f9-c19f54854605', '07ccd120-1caf-4c08-8f99-631ae11f170d', true, 'Arquitetura RAG Auditável para Consulta em Acervos de Teses e Dissertações Brasileiras', 'Pipeline de Recuperação Aumentada por Geração (RAG) com citação direta de parágrafos e mitigação de alucinações em artigos científicos em português.', 'Este trabalho propõe um indexador semântico denso e esparso (busca híbrida BM25 + embeddings multilíngues) projetado especificamente para bibliotecas digitais universitárias brasileiras. O sistema permite que pesquisadores realizem perguntas complexas e recebam respostas fundamentadas exclusivamente nos trechos recuperados, acompanhadas de referências ABNT automatizadas.', array['Redução de 78% na taxa de alucinação factual em comparação ao uso de LLMs sem recuperação contextual.', 'Indexação vetorial de mais de 12.500 dissertações e artigos em língua portuguesa.', 'Interface de avaliação aberta para validação por docentes e bibliotecários.']::text[], 'Utilizamos segmentação semântica sensível à estrutura de artigos acadêmicos (Resumo, Metodologia, Resultados e Referências), armazenamento vetorial no PostgreSQL via pgvector e re-ranking cruzado antes da etapa de geração.', '[{"name":"arquitetura_rag_academico_ufrj.pdf","size":"1.9 MB","type":"Artigo Técnico PDF"},{"name":"benchmark_alucinacoes_ptbr.csv","size":"620 KB","type":"Resultados CSV"}]'::jsonb, 'Universidade Federal do Rio de Janeiro (UFRJ)', 'Inteligência Artificial', 'Iniciação Científica', 'Em andamento', date '2025-05-10', 'mar. 2024 - dez. 2025', array['IA Generativa', 'LLMs', 'RAG', 'Python', 'PostgreSQL']::text[], 'https://github.com/capyfolio-demo/rag-acervos-academicos', 'ai-network', 'https://images.unsplash.com/photo-1620712943543-bcc4688e7485?w=1000&auto=format&fit=crop&q=80', 68) on conflict (id) do nothing;
insert into public.project_authors (project_id, profile_id, position) values ('442306d0-c2fb-437b-88f9-c19f54854605', '07ccd120-1caf-4c08-8f99-631ae11f170d', 0) on conflict do nothing;
insert into public.project_authors (project_id, profile_id, position) values ('442306d0-c2fb-437b-88f9-c19f54854605', 'b6f3063e-e60e-49f5-bd47-2e551099e279', 1) on conflict do nothing;
insert into public.projects (id, created_by, is_sample, title, short_description, summary, key_results, methodology, files, institution, area, type, status, project_date, period, tags, url, visual_type, media_url, favorites_base) values ('b8d640a9-2ac8-463d-b71b-524c4030527e', '5a885de2-e187-4ab4-8fba-cdcd355142b5', true, 'CapyVision: Rastreamento Tático de Baixa Latência para Futebol de Robôs Autônomos', 'Sistema em Python e C++ para calibração óptica, detecção cromática e predição de trajetória de robôs móveis a 120 quadros por segundo.', 'Desenvolvimento de um motor de visão computacional de alto desempenho para equipes universitárias de robótica autônoma. O projeto combina filtros de Kalman Estendidos (EKF) com um painel de telemetria em React para diagnóstico em tempo real durante partidas oficiais.', array['Redução do tempo de inferência visual de 14.2ms para 3.8ms por quadro.', 'Estabilidade de rastreamento superior a 99% sob variações de iluminação.', 'Painel web interativo com reprodução de jogadas e mapas de calor.']::text[], 'Captura via câmera global industrial, segmentação em espaço de cor HSV calibrado por algoritmos genéticos e filtragem estocástica para compensação do atraso de rádio.', '[{"name":"artigo_sbrt_capyvision.pdf","size":"3.1 MB","type":"Artigo PDF"}]'::jsonb, 'Ibmec Rio', 'Visão Computacional', 'Projeto de Engenharia', 'Concluído', date '2025-04-19', 'ago. 2024 - jul. 2025', array['Visão Computacional', 'Python', 'C++', 'React']::text[], 'https://github.com/capyfolio-demo/capyvision', 'standard', 'https://images.unsplash.com/photo-1485827404703-89b55fcc595e?w=1000&auto=format&fit=crop&q=80', 35) on conflict (id) do nothing;
insert into public.project_authors (project_id, profile_id, position) values ('b8d640a9-2ac8-463d-b71b-524c4030527e', '5a885de2-e187-4ab4-8fba-cdcd355142b5', 0) on conflict do nothing;
insert into public.projects (id, created_by, is_sample, title, short_description, summary, key_results, methodology, files, institution, area, type, status, project_date, period, tags, url, visual_type, media_url, favorites_base) values ('0e0fb633-def2-4e05-ad05-b8ce24c74a6b', 'fa02873d-5b68-49f4-8a23-819e8ad37d10', true, 'SabiáEdu: Plataforma Aberta de Apoio à Revisão Estrutural de Textos Acadêmicos', 'Ambiente colaborativo web para orientação de escrita científica e revisão por pares entre estudantes de graduação.', 'Plataforma desenvolvida para auxiliar estudantes de primeira metade da graduação na estruturação de relatórios de pesquisa, resumos expandidos e artigos científicos, conectando veteranos e monitores em rodadas estruturadas de revisão.', array['Adotado por 6 ligas acadêmicas e grupos PET no Rio de Janeiro.', 'Mais de 420 resumos revisados colaborativamente no último semestre.']::text[], 'Arquitetura fullstack baseada em React, TypeScript, Node.js e PostgreSQL com foco em acessibilidade web (WCAG AA).', '[{"name":"documentacao_arquitetura_sabiaedu.pdf","size":"1.5 MB","type":"Documentação PDF"}]'::jsonb, 'PUC-Rio & Ibmec Rio', 'Engenharia de Software', 'Projeto de Extensão', 'Em andamento', date '2025-05-02', 'fev. 2025 - dez. 2025', array['React', 'TypeScript', 'Node.js', 'PostgreSQL']::text[], 'https://github.com/capyfolio-demo/sabia-edu', 'standard', 'https://images.unsplash.com/photo-1522202176988-66273c2fd55f?w=1000&auto=format&fit=crop&q=80', 29) on conflict (id) do nothing;
