insert into public.projects (id, created_by, is_sample, title, short_description, summary, key_results, methodology, files, institution, area, type, status, project_date, period, tags, url, visual_type, media_url, favorites_base) values ('6082a412-5e2c-4152-aea8-2a8b5c3046ab', '23929862-501c-4488-8cb3-392a5f284efc', true, 'BioDock-BR: Triagem Virtual de Moléculas da Biodiversidade Brasileira com Graph Neural Networks', 'Modelos de aprendizado profundo geométrico aplicados à predição de afinidade molecular em bancos de dados de produtos naturais.', 'Investigação científica que aplica Redes Neurais em Grafos (GNNs) sobre estruturas moleculares catalogadas no NuBBE Database, acelerando a identificação de candidatos promissores contra alvos proteicos de doenças tropicais negligenciadas.', array['Triagem computacional de 54.000 compostos naturais em menos de 4 horas.', 'Validação cruzada com ferramentas clássicas de docking molecular.']::text[], 'Representação de ligações atômicas como grafos direcionados e treinamento supervisionado em PyTorch Geometric.', '[{"name":"poster_simposio_bioinformatica_usp.pdf","size":"2.8 MB","type":"Pôster Científico PDF"}]'::jsonb, 'Universidade de São Paulo (USP)', 'Bioinformática', 'Projeto de pesquisa', 'Em andamento', date '2025-04-14', 'jan. 2024 - nov. 2025', array['Bioinformática', 'Python', 'PyTorch', 'Pesquisa Acadêmica']::text[], 'https://github.com/capyfolio-demo/biodock-br', 'standard', 'https://images.unsplash.com/photo-1532187863486-abf9dbad1b69?w=1000&auto=format&fit=crop&q=80', 51) on conflict (id) do nothing;
insert into public.project_authors (project_id, profile_id, position) values ('6082a412-5e2c-4152-aea8-2a8b5c3046ab', '23929862-501c-4488-8cb3-392a5f284efc', 0) on conflict do nothing;
insert into public.projects (id, created_by, is_sample, title, short_description, summary, key_results, methodology, files, institution, area, type, status, project_date, period, tags, url, visual_type, media_url, favorites_base) values ('90fba419-43f3-4f5a-9063-b354a0f79001', '4fc6858c-87d0-4400-8673-e183eb4405c3', true, 'Plataforma de Otimização de Processos Tech com LLMs', 'Projeto prático desenvolvido para automação de fluxos acadêmicos utilizando Modelos de Linguagem, garantindo validação técnica, código aberto no GitHub e documentação rigorosa.', 'Projeto prático desenvolvido para automatizar e otimizar processos acadêmicos e internos de tecnologia, com foco em produtividade, documentação e tomada de decisão baseada em dados. O sistema integra IA generativa para reduzir retrabalho, organizar fluxos de tarefas e entregar entregáveis com mais velocidade e qualidade.', array['Redução de 40% no tempo de processamento de dados acadêmicos.', 'Arquitetura modular em React e microsserviços Python.', 'Repositório público com documentação completa e testes unitários.']::text[], 'A solução foi estruturada em frontend em React com TypeScript, backend em Node.js/Python para orquestração de fluxos e uso de LLMs para classificação e geração de insights. A implementação revisa processos acadêmicos em etapas, com testes, automação e documentação para facilitar manutenção e escalabilidade.', '[{"name":"arquitetura_llm_automacao.pdf","size":"1.8 MB","type":"Relatório PDF"},{"name":"backend_processos_llm.zip","size":"2.6 MB","type":"Código Backend"}]'::jsonb, 'Ibmec Rio', 'Fullstack & IA', 'Projeto Prático', 'Concluído', date '2025-12-15', 'ago. 2025 - dez. 2025', array['Python', 'LLMs', 'React', 'Docker']::text[], 'https://github.com/arthur/otimizacao-llm', 'standard', 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?w=1000&auto=format&fit=crop&q=80', 27) on conflict (id) do nothing;
insert into public.project_authors (project_id, profile_id, position) values ('90fba419-43f3-4f5a-9063-b354a0f79001', '4fc6858c-87d0-4400-8673-e183eb4405c3', 0) on conflict do nothing;
insert into public.events (id, is_sample, title, category, status, starts_at, ends_at, location, city, organizer, modality, tags, short_description, about_text, speakers, schedule, attendees_base) values ('8412e4bb-41c9-472e-a264-5f7aec515870', true, 'RAG e LLMs: aplicações e desafios na pesquisa acadêmica', 'Palestra', 'Inscrições abertas', (timestamp '2025-05-15 14:00' at time zone 'America/Sao_Paulo'), (timestamp '2025-05-15 18:00' at time zone 'America/Sao_Paulo'), 'Auditório do Instituto de Computação - UFF', 'Niterói, RJ', 'Universidade Federal Fluminense (UFF)', 'Presencial', array['IA Generativa', 'LLMs', 'RAG', 'Pesquisa Acadêmica']::text[], 'Palestra com especialistas da área de IA sobre o uso de Retrieval-Augmented Generation (RAG) e grandes modelos de linguagem (LLMs) em projetos acadêmicos, com foco em aplicações práticas, limitações e boas práticas.', 'O evento contará com palestras, demonstrações práticas e um espaço para dúvidas e networking. Será uma excelente oportunidade para estudantes e pesquisadores aprimorarem seus conhecimentos e conhecerem as últimas tendências da área, compreendendo como estruturar pipelines reprodutíveis, avaliar alucinações com rigor estatístico e publicar pesquisas sólidas no ecossistema brasileiro.', '[{"id":"sp1","name":"Ana Clara Souza","role":"Pesquisadora - UFRJ","avatar":"https://images.unsplash.com/photo-1580489944761-15a19d654956?w=300&auto=format&fit=crop&q=80","topic":"Arquiteturas de Recuperação Densa e Avaliação de Factualidade em Português"},{"id":"sp2","name":"Lucas Martins","role":"Professor - UFF","avatar":"https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=300&auto=format&fit=crop&q=80","topic":"Ética, Reprodutibilidade Científica e LLMs Abertos na Universidade"}]'::jsonb, '[{"time":"14:00 - 14:30","title":"Credenciamento Acadêmico e Abertura Institucional","speaker":"Coordenação do Instituto de Computação (IC/UFF)"},{"time":"14:30 - 15:45","title":"Palestra Técnica: RAG na Prática — Indexação Semântica e Mitigação de Alucinações","speaker":"Ana Clara Souza (Pesquisadora - UFRJ)"},{"time":"15:45 - 17:00","title":"Palestra & Demo: Desafios Metodológicos de LLMs na Pesquisa Universitária","speaker":"Prof. Dr. Lucas Martins (UFF)"},{"time":"17:00 - 18:00","title":"Mesa de Perguntas, Café Acadêmico e Networking entre Estudantes","speaker":"Aberto a todos os inscritos (Certificado de 4h AAC)"}]'::jsonb, 148) on conflict (id) do nothing;
insert into public.events (id, is_sample, title, category, status, starts_at, ends_at, location, city, organizer, modality, tags, short_description, about_text, speakers, schedule, attendees_base) values ('be1d9c2d-dfbf-4303-934b-ed0863e6a5cb', true, 'Simpósio Fluminense de Ciência de Dados Espaciais e Cidades Resilientes', 'Simpósio', 'Inscrições abertas', (timestamp '2025-06-22 09:00' at time zone 'America/Sao_Paulo'), (timestamp '2025-06-22 17:00' at time zone 'America/Sao_Paulo'), 'Auditório Central COPPE - UFRJ', 'Rio de Janeiro, RJ', 'UFRJ & UFF', 'Presencial e Híbrido', array['Dados e Análise', 'GeoPandas', 'Python', 'Rio de Janeiro']::text[], 'Encontro interuniversitário dedicado à apresentação de projetos de Iniciação Científica e extensão que utilizam dados geoespaciais abertos para monitoramento climático e urbano.', 'O simpósio reúne estudantes de graduação, pós-graduação e gestores públicos para debater o uso de ferramentas abertas (QGIS, GeoPandas, PostGIS e imagens de satélite CBERS-4A) na prevenção de desastres naturais e melhoria da qualidade ambiental nas cidades brasileiras.', '[{"id":"sp3","name":"Gabriel Costa","role":"Pesquisador IC - UFF","avatar":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=300&auto=format&fit=crop&q=80","topic":"Mapeamento Espacial da Qualidade do Ar no Rio de Janeiro"},{"id":"sp4","name":"Profa. Helena Vasconcelos","role":"Docente - UFRJ","avatar":"https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=300&auto=format&fit=crop&q=80","topic":"Sensoriamento Remoto e Políticas Públicas Baseadas em Evidências"}]'::jsonb, '[{"time":"09:00 - 10:30","title":"Painel de Abertura: Dados Abertos Ambientais no Estado do Rio de Janeiro","speaker":"Profa. Helena Vasconcelos (UFRJ)"},{"time":"11:00 - 12:30","title":"Mostra de Portfólios Estudantis CapyFolio","speaker":"Apresentação Oral de Trabalhos"},{"time":"14:00 - 17:00","title":"Oficina Prática: GeoPandas e PostGIS para Análise Urbana","speaker":"Laboratório de Geoprocessamento UFF"}]'::jsonb, 210) on conflict (id) do nothing;
insert into public.posts (id, author_id, is_sample, category, content, related_project_id, related_event_id, likes_base, created_at) values ('3f58de1b-4417-48ff-9f34-af70682215a8', 'b6f3063e-e60e-49f5-bd47-2e551099e279', true, 'Dados e Análise', 'Acabamos de atualizar os mapas de interpolação espacial e o repositório do nosso projeto ''Análise espacial da qualidade do ar no Rio de Janeiro usando dados abertos'', desenvolvido em parceria com a Mariana Alves na UFF! Consolidamos os dados das estações de monitoramento com GeoPandas e PostgreSQL para identificar as zonas críticas de concentração de poluentes. Feedbacks de colegas da área ambiental e de dados são muito bem-vindos!', '3e7c8fc8-171b-4514-9686-83a230a95a1b', null, 54, now() - interval '3 hours') on conflict (id) do nothing;
insert into public.comments (id, post_id, author_id, author_name, author_institution, text, created_at) values ('211f9b53-c232-436e-afe0-cb22616e7b89', '3f58de1b-4417-48ff-9f34-af70682215a8', null, 'Ana Clara Souza', 'UFRJ', 'Excelente trabalho, Gabriel e Mariana! A visualização espacial ficou super clara e muito bem documentada.', now() - interval '1 hour') on conflict (id) do nothing;
insert into public.posts (id, author_id, is_sample, category, content, related_project_id, related_event_id, likes_base, created_at) values ('7e18a74d-ee89-44c6-9dc0-6822ecbc8e1e', 'c21bb9e1-f8a7-47cf-84f2-109835f3ee13', true, 'Palestra Oficial', 'Estão abertas as inscrições para a palestra ''RAG e LLMs: aplicações e desafios na pesquisa acadêmica'', que acontecerá no Auditório do Instituto de Computação da UFF em Niterói. Contaremos com a presença da pesquisadora Ana Clara Souza (UFRJ) e do Prof. Lucas Martins (UFF). Inscreva-se diretamente pela página do evento aqui no CapyFolio!', null, '8412e4bb-41c9-472e-a264-5f7aec515870', 92, now() - interval '6 hours') on conflict (id) do nothing;
insert into public.posts (id, author_id, is_sample, category, content, related_project_id, related_event_id, likes_base, created_at) values ('341f8c82-34ee-4a1c-af1a-3250d494f184', '5a885de2-e187-4ab4-8fba-cdcd355142b5', true, 'Visão Computacional', 'Compartilhando os resultados mais recentes do projeto CapyVision! Conseguimos atingir 120 FPS constantes no rastreamento tático de robôs autônomos combinando C++, Python e filtros de Kalman. A documentação técnica completa já está disponível no meu portfólio.', 'b8d640a9-2ac8-463d-b71b-524c4030527e', null, 41, now() - interval '1 day 2 hours') on conflict (id) do nothing;
